def assign_serial_no(apps, schema_editor):
    CharacterCertificate = apps.get_model("main", "CharacterCertificate")
    School = apps.get_model("main", "SchoolAdmin")
    #
    for school in School.objects.all():
        certificates = CharacterCertificate.objects.filter(school=school).order_by("id")
        serial_no = 1
        for certificate in certificates:
            certificate.serial_no = serial_no
            certificate.save(update_fields=["serial_no"])
            serial_no += 1


